def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False
    t = total // 2
    reach = [True] + [False] * t
    for x in nums:
        for s in range(t, x - 1, -1):
            if reach[s - x]:
                reach[s] = True
    return reach[t]

